                                $base_cost = isset($hotel_costs[$type]) ? $hotel_costs[$type] : 0;
                                
                                $base_cost += ($base_cost * ($hotel_markup_percentage / 100));
                                $final_total_cost = $base_cost / $currency;
                                
                                $lookup_key = $pkg['name'] . '|' . $name . '|' . $type;
