                                $occupancy_type = $occ_arr[0] ?? '';
                                if (strpos($occupancy_type, 'CWB') !== false) {
                                    $occupancy_cost = isset($occ_arr[1]) ? floatval($occ_arr[1]) : 0;

                                    // Calculate markup amount
