                        $cost_html .= '</td>';

                        $cwb_col_index++;
                    }
                }
                $cost_html .= '</tr>';
            }

            // Land Package Markup Per Person
            if (!empty($hotel_markup_percentage)) {
                $total_cols = 0;
                foreach ($hotel_costing_category_wise as $rating_key => $hotels) {
                    foreach ($hotels as $hotel_name => $categories) {
                        foreach ($categories as $cat => $occupancies) {
