                                            } else {
                                                $clean_category = $category;
                                            }
                                        if (strpos($clean_category, '(') !== false) {
                                            $parts = explode('(', $clean_category, 2);
                                            $prefix = trim($parts[0]);
                                            $category_id = $this->get_category_id_by_name($category, $hotel_name);
