                                                $cost_html .= $clean_category . '<img src="'.base_url('assets/images/camera_icon.png').'" alt="Room Category Icon" style="width: 30px;margin-left: 5px;vertical-align: middle;" ><br>';
                                                $cost_html .= '</a>';
                                            } else {
                                                $cost_html .= $clean_category . '<br>';
                                            }
                                        }
                                    }
                                } else {
                                    $cost_html .= 'NA';
                                }
                                $cost_html .= '</td>';
